documents = {
    "vendor_facts": "Our primary hosting vendor is Falcon Cloud.",
    "falcon_cloud_facts": "Falcon Cloud guarantees ninety nine point nine percent uptime.",
}

def hop_one_find_vendor():
    # hop one finds the missing vendor name
    return "Falcon Cloud" if "Falcon Cloud" in documents["vendor_facts"] else None

def hop_two_find_uptime(vendor_name):
    # hop two searches using the vendor name from hop one
    key = "falcon_cloud_facts"
    if vendor_name in documents[key]:
        return documents[key]
    return None

def multi_hop_rag(question):
    vendor_name = hop_one_find_vendor()
    if vendor_name is None:
        return "Could not resolve hop one."
    uptime_fact = hop_two_find_uptime(vendor_name)
    return f"Hop 1 found vendor: {vendor_name}. Hop 2 found: {uptime_fact}"

question = "What uptime does our hosting vendor guarantee?"
result = multi_hop_rag(question)
print("Multi-hop RAG result:")
print(result)
